'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'../..'),html=fs.readFileSync(path.join(root,'index.html'),'utf8');
const a=html.indexOf('function pcInsaneOriginText('),b=html.indexOf('function pcInsaneItemDraftHTML(',a);assert.ok(a>0&&b>a);const origin=new Function(html.slice(a,b)+'\nreturn pcInsaneOriginText;')();
const row=(inputRef,scope,rest={})=>({label:'测试',value:'1',insaneSource:{format:'community-large-v2',inputRef,scope,...rest}});
test('Round215 recognizes strictly verified basic sources and only editor-side origin',()=>{assert.match(origin(row('H18','name-only')),/H18 · 仅能力名称/);assert.match(origin(row('E32','count-only',{labelRef:'B32'})),/E32 · 仅数量/);assert.match(origin(row('B29','specialty',{gridRef:'I3'})),/B29 · 特技位置 I3/);});
test('Round215 unknown, private and mismatched provenance never renders in UI',()=>{for(const x of [row('P40','private-note'),row('E32','count-only',{labelRef:'B33'}),row('H99','name-only'),row('B29','specialty',{gridRef:'P40'}),row('E32','count-only',{labelRef:'B32',format:'untrusted'}),{}])assert.equal(origin(x),'');});
test('Round215 editor shows source only for Insane and HTML-escapes it',()=>{const a=html.indexOf('function pcGenericRuleEditorHTML('),b=html.indexOf('function pcProfileEditorHTML(',a);const text=html.slice(a,b);assert.match(text,/pcRuleTemplateKey\(pc\)==='insane'&&typeof pcInsaneOriginText==='function'&&pcInsaneOriginText\(row\)/);assert.match(text,/escapeHTML\(pcInsaneOriginText\(row\)\)/);assert.match(html,/\.pc-rule-source-ref\{[^}]*overflow-wrap:anywhere/);});
test('Round215 public HTML and final images do not render source metadata',()=>{const a=html.indexOf('const genericData=pcRuleCurrentData(pc),genericSection='),b=html.indexOf('const genericSkillHtml=',a);assert.ok(a>0&&b>a);assert.doesNotMatch(html.slice(a,b),/insaneSource|pcInsaneOriginText|inputRef/);assert.doesNotMatch(html.slice(a,b),/私人备注/);});
test('Round215 review, source retention and current workflows remain wired',()=>{for(const name of ['pl-browser-synthetic.yml','pl-native-restore-gate.yml'])assert.match(fs.readFileSync(path.join(root,'.github/workflows',name),'utf8'),/round215-insane-editor-provenance\.test\.cjs/);const sw=fs.readFileSync(path.join(root,'sw.js'),'utf8');assert.ok(sw.includes(html.match(/const APP_UI_VERSION = "([^\"]+)"/)?.[1]));});
